    /**
     * Estadísticas de tareas
     */
    public static function getTaskStatistics($processId = null, $dateFrom = null, $dateTo = null)
    {
        $c = new Criteria();

        if ($processId) {
            $c->addJoin(TaskInstancePeer::WORKFLOWINSTANCE_ID, WorkflowInstancePeer::WORKFLOWINSTANCE_ID, Criteria::INNER_JOIN);
            $c->add(WorkflowInstancePeer::BPMNPROCESS_ID, $processId);
        }

        if ($dateFrom) {
            $c->add(TaskInstancePeer::FECHA_CREACION, $dateFrom, Criteria::GREATER_EQUAL);
        }

        if ($dateTo) {
            $c->add(TaskInstancePeer::FECHA_CREACION, $dateTo, Criteria::LESS_EQUAL);
        }

        $tasks = TaskInstancePeer::doSelect($c);

        $stats = [
            'total' => count($tasks),
            'pending' => 0,
            'assigned' => 0,
            'completed' => 0,
            'overdue' => 0,
            'avg_completion_time' => 0
        ];

        $completionTimes = [];

        foreach ($tasks as $task) {
            $status = $task->getTaskInstanceStatusId();
            if (isset($stats[$status])) {
                $stats[$status]++;
            }

            // Verificar si está vencida
            if (
                $task->getFechaVencimiento() && $task->getFechaVencimiento('U') < time() &&
                in_array($status, [1, 2])
            ) {
                $stats['overdue']++;
            }

            // Calcular tiempo de finalización
            if ($status === 3 && $task->getFechaFin() && $task->getFechaAsignacion()) {
                $startTime = $task->getFechaAsignacion('U');
                $endTime = $task->getFechaFin('U');
                $completionTimes[] = ($endTime - $startTime) / 3600; // en horas
            }
        }

        if (!empty($completionTimes)) {
            $stats['avg_completion_time'] = array_sum($completionTimes) / count($completionTimes);
        }

        return $stats;
    }

