        if ($taskDefinition && $skipWithForms) {
            $formData = $taskDefinition->getFormData();
            if ($formData) {
                $formFields = json_decode($formData, true);
                if (is_array($formFields)) {
                    foreach ($formFields as $field) {
                        if (!empty($field['required'])) {
                            return ['success' => false, 'error' => 'Esta tarea requiere completar un formulario'];
                        }
                    }
                }
            }
        }

        // Completar la tarea
        /*$task->setTaskinstancestatusId(TaskInstanceStatusBpmn::completed);
        $task->setFechaCompletado(date('Y-m-d G:i:s'));
        $task->setFechaModificacion(date('Y-m-d G:i:s'));
        //$task->setCompletedBy($userId);

        if (!empty($comment)) {
            $task->setComentarios($comment);
        }

        $task->save();*/

        // Actualizar variables del workflow
        TaskDefinitionPeer::updateWorkflowVariables($task->getWorkflowInstance(), array());

        $engine = new WorkflowEngine();
        $nextTask = $engine->completeTask($taskId, $userId, array(), $comment);

        // Verificar si hay siguiente tarea para el usuario
        $hasNextTask = false;
        if ($nextTask != null) {
            $hasNextTask = ($nextTask->getUsuarioId() == $userId);
        }

        // Agregar info de siguiente tarea si existe y es del mismo usuario
        if ($nextTask) {
            $response['has_next_task'] = $hasNextTask;
            $response['next_task'] = [
                'id' => $nextTask->getTaskinstanceId(),
                'task_name' => $nextTask->getTaskName(),
                'assigned_to_me' => ($nextTask->getUsuarioId() == $userId)
            ];
        } else {
            $response['has_next_task'] = $hasNextTask;
        }

        // Registrar en log
        self::logTaskAction($task, 'approved', $userId, $comment);

        // Avanzar el workflow
        //self::advanceWorkflow($task);

        $response['success'] = true;
        $response['message'] = 'Tarea aprobada correctamente';

        return $response;
    }

    /**
     * Procesa el rechazo de una tarea individual
     * 
     * @param int $taskId ID de la tarea
     * @param int $userId ID del usuario que rechaza
     * @param string $reason Motivo del rechazo
     * @return array Resultado de la operación
     */
    public static function processTaskRejection($taskId, $userId, $reason)
    {
        // Obtener la tarea
        $task = TaskInstancePeer::retrieveByPK($taskId);

        if (!$task) {
            return ['success' => false, 'error' => 'Tarea no encontrada'];
        }

        // Verificar estado
        if (!in_array($task->getTaskinstancestatusId(), [TaskInstanceStatusBpmn::pending, TaskInstanceStatusBpmn::assigned])) {
            return ['success' => false, 'error' => 'La tarea no está pendiente'];
        }

        // Verificar asignación
        if ($task->getUsuarioId() && $task->getUsuarioId() != $userId) {
            return ['success' => false, 'error' => 'No tienes permiso para rechazar esta tarea'];
        }

        // Rechazar la tarea
        $task->setTaskinstancestatusId(TaskInstanceStatusBpmn::rejected);
        $task->setFechaCompletado(date('Y-m-d G:i:s'));
        $task->setFechaModificacion(date('Y-m-d G:i:s'));
        //$task->setCompletedBy($userId);
        $task->setComentarios($reason);
        $task->save();

        // Registrar en log
        self::logTaskAction($task, 'rejected', $userId, $reason);

        // Manejar el workflow según el rechazo
        self::handleWorkflowRejection($task);

        return ['success' => true];
    }

    /**
     * Avanza el workflow después de completar una tarea
     */
    public static function advanceWorkflow($task)
    {
        try {
            $workflowInstance = $task->getWorkflowInstance();

            if (!$workflowInstance) {
                return;
            }

            // Usar el motor de workflow para avanzar
            if (class_exists('WorkflowEngine')) {
                $engine = new WorkflowEngine();
                $engine->advance($workflowInstance);
            }
        } catch (Exception $e) {
            error_log('Error al avanzar workflow: ' . $e->getMessage());
        }
    }

    /**
     * Maneja el workflow cuando se rechaza una tarea
     */
    public static function handleWorkflowRejection($task)
    {
        try {
            $workflowInstance = $task->getWorkflowInstance();

            if (!$workflowInstance) {
                return;
            }

            // Obtener configuración de rechazo del proceso
            $taskDefinition = $task->getTaskDefinition();

            if ($taskDefinition) {
                $rejectionBehavior = $taskDefinition->getRejectionBehavior();

                switch ($rejectionBehavior) {
                    case 'terminate':
                        // Terminar el workflow
                        $workflowInstance->setWorkflowstatusId(WorkflowInstanceStatusBpmn::terminated);
                        $workflowInstance->setFechaCompletado(date('Y-m-d G:i:s'));
                        $workflowInstance->setFechaModificacion(date('Y-m-d G:i:s'));
                        $workflowInstance->save();
                        break;

                    case 'return_to_previous':
                        // Volver a la tarea anterior
                        // Implementar según la lógica del proceso
                        break;

                    case 'continue':
                    default:
                        // Continuar con el flujo (por defecto)
                        if (class_exists('WorkflowEngine')) {
                            $engine = new WorkflowEngine();
                            $engine->handleRejection($workflowInstance, $task);
                        }
                        break;
                }
            }
        } catch (Exception $e) {
            error_log('Error al manejar rechazo de workflow: ' . $e->getMessage());
        }
    }

